// Lambda snippet calling SageMaker endpoint
const aws = require('aws-sdk');
const Sage = new aws.SageMakerRuntime();
exports.handler = async (event) => {
  const payload = event.records.map(r => r.data).join('\n');
  const res = await Sage.invokeEndpoint({ EndpointName: 'sentiment-intent', ContentType: 'text/plain', Body: payload }).promise();
  return res;
}
